         private val log = LoggerFactory.getLogger(HeaderCommentRule::class.java)
         val hyphenRegex = Regex("""\d+-\d+""")
         val afterCopyrightRegex = Regex("""((©|\([cC]\))+ *\d+)""")
         val curYear = LocalDate.now().year
     }
 }

